CREATE TABLE IF NOT EXISTS public.employee_kpi_profiles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL UNIQUE, category text NOT NULL CHECK(category IN ('operations','sales','future')), active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS public.employee_kpi_assignments (user_id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, profile_id uuid NOT NULL REFERENCES public.employee_kpi_profiles(id), active boolean NOT NULL DEFAULT true, assigned_at timestamptz NOT NULL DEFAULT now(), assigned_by uuid REFERENCES auth.users(id));
CREATE TABLE IF NOT EXISTS public.employee_kpi_targets (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), profile_id uuid NOT NULL REFERENCES public.employee_kpi_profiles(id) ON DELETE CASCADE, metric_key text NOT NULL, target_value numeric NOT NULL CHECK(target_value>=0), effective_from date NOT NULL DEFAULT current_date, created_by uuid REFERENCES auth.users(id), UNIQUE(profile_id,metric_key,effective_from));
CREATE TABLE IF NOT EXISTS public.sales_leads (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), company_name text NOT NULL, contact_person text, phone text, email text, location text, source text, assigned_to uuid REFERENCES auth.users(id), status text NOT NULL DEFAULT 'new' CHECK(status IN ('new','contacted','replied','interested','sample_planned','sample_sent','follow_up','converted','not_interested','no_response','lost')), last_contact_at timestamptz, next_follow_up_at timestamptz, notes text, converted_client_id uuid REFERENCES public.clients(id), converted_branch_id uuid REFERENCES public.branches(id), created_at timestamptz NOT NULL DEFAULT now(), created_by uuid REFERENCES auth.users(id));
CREATE TABLE IF NOT EXISTS public.lead_activities (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), lead_id uuid NOT NULL REFERENCES public.sales_leads(id) ON DELETE CASCADE, activity_type text NOT NULL CHECK(activity_type IN ('call','whatsapp','visit','email','note','follow_up','sample_planned','sample_sent','response_received')), outcome text, notes text, performed_by uuid NOT NULL REFERENCES auth.users(id), performed_at timestamptz NOT NULL DEFAULT now(), next_follow_up_at timestamptz);
CREATE TABLE IF NOT EXISTS public.lead_samples (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), lead_id uuid NOT NULL REFERENCES public.sales_leads(id) ON DELETE CASCADE, product_id uuid REFERENCES public.products(id), product_name_snapshot text, quantity numeric CHECK(quantity IS NULL OR quantity>0), status text NOT NULL DEFAULT 'not_planned' CHECK(status IN ('not_planned','planned','sent','delivered','follow_up_due','converted','no_conversion')), sent_at timestamptz, delivered_at timestamptz, follow_up_due_at timestamptz, result text, created_at timestamptz NOT NULL DEFAULT now(), created_by uuid REFERENCES auth.users(id));
CREATE INDEX IF NOT EXISTS idx_sales_leads_follow_up ON public.sales_leads(next_follow_up_at) WHERE status NOT IN ('converted','lost','not_interested');
ALTER TABLE public.employee_kpi_profiles ENABLE ROW LEVEL SECURITY; ALTER TABLE public.employee_kpi_assignments ENABLE ROW LEVEL SECURITY; ALTER TABLE public.employee_kpi_targets ENABLE ROW LEVEL SECURITY; ALTER TABLE public.sales_leads ENABLE ROW LEVEL SECURITY; ALTER TABLE public.lead_activities ENABLE ROW LEVEL SECURITY; ALTER TABLE public.lead_samples ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "KPI admin read" ON public.employee_kpi_profiles;
CREATE POLICY "KPI admin read" ON public.employee_kpi_profiles FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'admin') OR public.has_role(auth.uid(),'moderator'));
DROP POLICY IF EXISTS "Lead operators read" ON public.sales_leads;
CREATE POLICY "Lead operators read" ON public.sales_leads FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'admin') OR public.has_role(auth.uid(),'moderator') OR assigned_to=auth.uid());
DROP POLICY IF EXISTS "Lead operators write" ON public.sales_leads;
CREATE POLICY "Lead operators write" ON public.sales_leads FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin') OR public.has_role(auth.uid(),'moderator') OR assigned_to=auth.uid()) WITH CHECK(public.has_role(auth.uid(),'admin') OR public.has_role(auth.uid(),'moderator') OR assigned_to=auth.uid());
DROP POLICY IF EXISTS "Lead activity operators" ON public.lead_activities;
CREATE POLICY "Lead activity operators" ON public.lead_activities FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin') OR public.has_role(auth.uid(),'moderator') OR performed_by=auth.uid()) WITH CHECK(public.has_role(auth.uid(),'admin') OR public.has_role(auth.uid(),'moderator') OR performed_by=auth.uid());
DROP POLICY IF EXISTS "Lead sample operators" ON public.lead_samples;
CREATE POLICY "Lead sample operators" ON public.lead_samples FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin') OR public.has_role(auth.uid(),'moderator')) WITH CHECK(public.has_role(auth.uid(),'admin') OR public.has_role(auth.uid(),'moderator'));
GRANT SELECT ON public.employee_kpi_profiles,public.employee_kpi_assignments,public.employee_kpi_targets TO authenticated; GRANT SELECT,INSERT,UPDATE ON public.sales_leads,public.lead_activities,public.lead_samples TO authenticated; GRANT ALL ON public.employee_kpi_profiles,public.employee_kpi_assignments,public.employee_kpi_targets,public.sales_leads,public.lead_activities,public.lead_samples TO service_role;
